head.script:
// 마지막으로 생성한 Submission ID (ID 변경 후 재생성 시 이전 Submission 정리용)
scwin.sbmID = "";



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Submission > P > id]<br/>Submission 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 Submission 컴포넌트를 구별할 수 있는 유일값을 문자열로 설정할 수 있어야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다."
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 생성 (Submission 은 화면에 표시되지 않으므로 grp_comp 에는 안내 라벨만 생성)
scwin.comp_init = async function () {
    $c.gcm.createLabel('label="Submission 은 화면에 표시되지 않는 컴포넌트입니다.\n[절차] ID 입력 -> Target 재생성\n[확인] getSubmission 버튼으로 입력한 ID 의 Submission 조회 결과 확인\n[참고] 예약어(예: scwin, $p) 입력 후 Target 재생성 시 버튼 동작과 콘솔 오류 확인"', '', 'label1');

    // 조건 설정
    let cID = con_ID.getValue();

    // ID 를 바꿔 재생성하는 경우 이전 ID 의 Submission 삭제 (동일 ID 는 createSubmission 이 기존 것을 교체)
    if (scwin.sbmID !== "" && scwin.sbmID !== cID && $p.getSubmission(scwin.sbmID)) {
        $p.deleteSubmission(scwin.sbmID);
    }

    // comp 생성
    scwin.target1 = await $c.gcm.createBasicSubmission({}, cID);
    scwin.sbmID = cID;
};



// validation 1, 2 판정 출력 : 입력한 ID 로 조회한 Submission 의 id 와 현재 Scope 의 Submission 목록
scwin.btn_getSubmission_onclick = function (e) {
    let cID = scwin.sbmID;
    let objSubmission = $p.getSubmission(cID);
    let arrList = $p.getSubmissionList().map(function (item) {
        return (typeof item === "string") ? item : item.id;
    });

    wf_body_bottom.getObj("scwin").setReturnValue("getSubmission(" + cID + ") -> id : " + (objSubmission ? objSubmission.id : objSubmission) + " / getSubmissionList : [" + arrList.join(", ") + "]");
};
